 */
export const MODELS = {
  cheap: CATALOG['claude-haiku-4-5-20251001'],
  balanced: CATALOG['claude-sonnet-5'],
  frontier: CATALOG['claude-opus-5'],
  local: CATALOG['ollama-chat'],
  // TODO(студент): роль `embed` навмисно вказує на локальну модель — курс не
